/bin/bash -lc "python - <<'PY'
import numpy as np
from PIL import Image
from scipy.ndimage import gaussian_filter
im=np.array(Image.open('first_frame.png')).astype(float);g=im.mean(2)
for kind,a in [('gray',g),('detail',g-gaussian_filter(g,3)),('edges',np.hypot(*np.gradient(g))),('color',im[:,:,0]-im[:,:,2])]:
 print('\\n',kind,'x100-195 every pixel')
 for y in range(0,102):
  if kind=='gray': s=''.join(' .,:;-~+=*#%@'[min(11,int(v/180*12))] for v in a[y,100:195])
  elif kind=='detail':s=''.join('X' if v<-30 else 'x' if v<-15 else '-' if v<-6 else '.' if v<-2.5 else ' ' if v<2.5 else ':' if v<6 else '+' if v<15 else '*' if v<30 else '#' for v in a[y,100:195])
  elif kind=='edges':s=''.join(' ' if v<2 else '.' if v<5 else ':' if v<10 else '+' if v<20 else '#' if v<40 else '@' for v in a[y,100:195])
  else: s=''.join(' ' if v<5 else '.' if v<15 else '+' if v<30 else '#' if v<60 else '@' for v in a[y,100:195])
  print(f'{y:3}',s)
PY"
